// Deterministic local raster fixtures, not advertiser content or billable traffic.
(function(root){
  'use strict';
  const poster='data:image/png;base64,';
  const animation='data:image/gif;base64,';
  const base={schemaVersion:1,id:'officialDemo',campaignId:'opendeskDemo',advertiser:'OpenDesk 官方示例',title:'重复的操作，交给自动化。',description:'从一次操作，到可验证、可重复运行的自动化。',cta:'预览详情',action:{kind:'preview'}};
  function sample(kind){
    const result=Object.assign({},base,{id:'demo'+kind,layout:kind==='text'?'text':kind==='mixed'?'image-text':'image'});
    if(kind!=='text')result.media={kind:kind==='animated'?'animated-image':'image',src:kind==='animated'?animation:poster,poster,alt:'OpenDesk 本地示例：Agent → Verify → Reuse'};
    return result;
  }
  root.OpenDeskPromotionSamples=Object.freeze({sample,poster,animation});
  if(typeof module==='object'&&module.exports)module.exports=root.OpenDeskPromotionSamples;
})(globalThis);
